def test_main_does_not_repeat_key_down_for_held_key():
    # meridian: unit_id=28faeb62248a requirement=3-4
    mock_fd = 42
    mock_saved = ['saved']
    
    with unittest.mock.patch.object(sys.stdin, 'fileno', return_value=mock_fd), \
         unittest.mock.patch.object(tui.termios, 'tcgetattr', return_value=mock_saved), \
         unittest.mock.patch.object(tui.termios, 'tcsetattr'), \
         unittest.mock.patch.object(tui.tty, 'setcbreak'), \
         unittest.mock.patch('tui.select.select') as mock_select, \
         unittest.mock.patch.object(sys.stdin, 'read') as mock_read, \
         unittest.mock.patch('tui.time.monotonic') as mock_time, \
         unittest.mock.patch('builtins.print'), \
         unittest.mock.patch.object(tui, 'NoteEngine') as mock_engine_class:
        
        mock_engine = unittest.mock.MagicMock()
        mock_engine_class.return_value = mock_engine
        mock_select.side_effect = [
            ([sys.stdin], [], []),  # 'a' first time
            ([sys.stdin], [], []),  # 'a' repeated (held)
            ([sys.stdin], [], []),  # 'q'
        ]
        mock_read.side_effect = ['a', 'a', 'q']
        mock_time.side_effect = [0.0, 0.0, 0.01, 0.02, 0.03]
        
        main()
        
        # key_down should only be called once for 'a', not twice
        assert mock_engine.key_down.call_count == 1
        mock_engine.key_down.assert_called_with('A')
